INSERT INTO `flowcharts` (`id`, `title`, `description`, `code`, `user_id`, `created_at`, `updated_at`) VALUES
(1, 'مدیر', '', 'flowchart LR\n    A([شروع]) --> B[\"صفحه ورود مدیر\\n(Livewire: LoginForm\\nیا AuthController)\"]\n    B --> C{\"اعتبارسنجی موفق؟\"}\n    C -- خیر --> B\n    C -- بله --> D[\"داشبورد مدیریت\\n(DashboardController\\nیا Livewire: Admin.Dashboard)\"]\n\n    D --> E[\"مدیریت کاربران\\n(UserController\\nیا Livewire: Admin.Users.Index)\"]\n    D --> F[\"مدیریت دسته‌بندی‌ها\\n(CategoryController\\nیا Livewire: Admin.Categories.Index)\"]\n    D --> G[\"مدیریت محصولات\\n(ProductController\\nیا Livewire: Admin.Product.Index)\"]\n    D --> H[\"مدیریت تأمین‌کنندگان\\n(SupplierController\\nیا Livewire: Admin.Suppliers.Index)\"]\n    D --> I[\"مدیریت صفحات سئو\\n(SeoController\\nیا Livewire: Admin.Seo.Index)\"]\n    D --> J[\"مدیریت قیمت‌های خرده‌فروشی\\n(RetailPriceController\\nیا Livewire: Admin.RetailPrices.Index)\"]\n    D --> K[\"تنظیمات سیستم\\n(AppServiceProvider یا فایل‌های Config)\"]\n    D --> L[\"خروج\\n(Livewire Action: Logout)\"]\n\n    %% جزئیات مدیریت کاربران\n    E --> E1[لیست کاربران]\n    E1 --> E2[\"ایجاد کاربر\\n(create → store)\"]\n    E1 --> E3[\"ویرایش کاربر\\n(edit → update)\"]\n    E1 --> E4[حذف کاربر]\n\n    %% جزئیات دسته‌بندی‌ها\n    F --> F1[لیست دسته‌بندی‌ها]\n    F1 --> F2[\"ایجاد دسته‌بندی\\n(create → store)\"]\n    F1 --> F3[\"ویرایش دسته‌بندی\\n(edit → update)\"]\n    F1 --> F4[حذف دسته‌بندی]\n\n    %% جزئیات محصولات\n    G --> G1[لیست محصولات]\n    G1 --> G2[\"ایجاد محصول\\n(create → store)\"]\n    G1 --> G3[\"ویرایش محصول\\n(edit → update)\"]\n    G1 --> G4[حذف محصول]\n\n    %% جزئیات تأمین‌کنندگان\n    H --> H1[لیست تأمین‌کنندگان]\n    H1 --> H2[\"ایجاد تأمین‌کننده\\n(create → store)\"]\n    H1 --> H3[\"ویرایش تأمین‌کننده\\n(edit → update)\"]\n    H1 --> H4[حذف تأمین‌کننده]\n\n    %% جزئیات صفحات سئو\n    I --> I1[لیست صفحات سئو]\n    I1 --> I2[\"ایجاد صفحه سئو\\n(create → store)\"]\n    I1 --> I3[\"ویرایش صفحه سئو\\n(edit → update)\"]\n    I1 --> I4[حذف صفحه سئو]\n\n    %% جزئیات قیمت‌های خرده‌فروشی\n    J --> J1[لیست قیمت‌ها]\n    J1 --> J2[\"ایجاد قیمت\\n(create → store)\"]\n    J1 --> J3[\"ویرایش قیمت\\n(edit → update)\"]\n    J1 --> J4[حذف قیمت]\n\n    %% حلقه خروج\n    L --> B\n', 1, '2026-05-31 23:09:44', '2026-05-31 23:26:06'),
(2, 'تامین کننده', '', 'flowchart LR\n    A([شروع]) --> B[\"صفحه ورود تأمین‌کننده\\n(Livewire: LoginForm\\nیا AuthController)\"]\n    B --> C{\"اعتبارسنجی موفق؟\"}\n    C -- خیر --> B\n    C -- بله --> D[\"داشبورد تأمین‌کننده\\n(DashboardController\\nیا Livewire: Supplier.Dashboard)\"]\n\n    D --> E[\"مدیریت محصولات\\n(ProductController\\nیا Livewire: MyProducts)\"]\n    D --> F[\"مدیریت قیمت‌گذاری\\n(PriceController\\nیا Livewire: Supplier.Pricing)\"]\n    D --> G[\"مدیریت گالری تصاویر\\n(GalleryController)\"]\n    D --> H[\"گزارش‌ها و آمار\\n(AnalyticsController)\"]\n    D --> I[\"ویرایش پروفایل\\n(ProfileController)\"]\n    D --> J[\"خروج\\n(Livewire Action: Logout)\"]\n\n%% جزئیات مدیریت محصولات\n    E --> E1[لیست محصولات]\n    E1 --> E2[\"ایجاد محصول\\n(create → store)\"]\n    E1 --> E3[\"ویرایش محصول\\n(edit → update)\"]\n    E1 --> E4[حذف محصول]\n\n%% جزئیات مدیریت قیمت‌گذاری\n    F --> F1[لیست قیمت‌ها]\nF1 --> F2[\"ویرایش قیمت\\n(edit → update)\"]\n\n%% جزئیات گالری تصاویر\nG --> G1[لیست گالری محصولات]\nG1 --> G2[\"افزودن تصویر\\n(create → store)\"]\nG1 --> G3[حذف تصویر]\n\n%% جزئیات گزارش‌ها و آمار\nH --> H1[انتخاب بازه زمانی و فیلترها]\nH1 --> H2[نمایش نمودارها و خروجی]\n\n%% جزئیات ویرایش پروفایل\nI --> I1[فرم ویرایش پروفایل]\nI1 --> I2[ثبت تغییرات]\n\n%% حلقه خروج\nJ --> B\n', 1, '2026-05-31 23:35:16', '2026-05-31 23:35:16');
